class Gradebook:
    def __init__(self) -> None:
        # Store assignments: {name: {"weight": float, "kind": str}}
        self.assignments = {}
        # Store grades: {student: {assignment: grade}}
        self.grades = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        if kind not in ["homework", "quiz"]:
            raise ValueError("kind must be 'homework' or 'quiz'")
        self.assignments[name] = {"weight": weight, "kind": kind}

    def record(self, student: str, assignment: str, grade: float) -> None:
        """Record a grade for a student on an assignment."""
        if grade < 2.0 or grade > 5.0:
            raise ValueError("Grade must be between 2.0 and 5.0")
        if assignment not in self.assignments:
            raise ValueError(f"Assignment '{assignment}' not found")

        if student not in self.grades:
            self.grades[student] = {}
        self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        """Calculate weighted average for a student."""
        if student not in self.grades:
            # If student has no grades, calculate average with all assignments as 2.0
            total_weighted_sum = 0.0
            total_weight = 0.0
            for assignment_name, assignment_info in self.assignments.items():
                total_weighted_sum += 2.0 * assignment_info["weight"]
                total_weight += assignment_info["weight"]
            if total_weight == 0.0:
                return 2.0
            return round(total_weighted_sum / total_weight, 2)

        # Get all assignments for this student
        student_grades = self.grades[student]

        # Separate homework and quiz grades
        homework_grades = []
        quiz_grades = []

        for assignment_name, assignment_info in self.assignments.items():
            if assignment_info["kind"] == "homework":
                grade = student_grades.get(assignment_name, 2.0)
                homework_grades.append((assignment_name, grade, assignment_info["weight"]))
            else:  # quiz
                grade = student_grades.get(assignment_name, 2.0)
                quiz_grades.append((assignment_name, grade, assignment_info["weight"]))

        # Handle quiz dropping: if more than one quiz, drop the lowest grade
        if len(quiz_grades) > 1:
            # Sort by grade (ascending) to find the lowest
            quiz_grades.sort(key=lambda x: x[1])
            # Drop the first (lowest) quiz grade
            quiz_grades = quiz_grades[1:]

        # Calculate weighted sum and total weight
        total_weighted_sum = 0.0
        total_weight = 0.0

        # Add homework grades
        for _, grade, weight in homework_grades:
            total_weighted_sum += grade * weight
            total_weight += weight

        # Add quiz grades (after dropping lowest if needed)
        for _, grade, weight in quiz_grades:
            total_weighted_sum += grade * weight
            total_weight += weight

        # Handle case where there are no assignments
        if total_weight == 0.0:
            return 2.0

        # Calculate and round to two decimal places
        result = total_weighted_sum / total_weight
        return round(result, 2)
